lxml._elementpath.xpath_tokenizer:
def xpath_tokenizer(pattern, namespaces=None):
    default_namespace = ((namespaces.get(None) or namespaces.get('')) if namespaces else None)
    parsing_attribute = False
    for token in xpath_tokenizer_re.findall(pattern):
        (ttype, tag) = token
        if (tag and tag[0] != '{'):
            if ':' in tag:
                (prefix, uri) = tag.split(':', 1)
                try:
                    if not namespaces:
                        raise KeyError
                    yield (ttype, '{%s}%s' % (namespaces[prefix], uri))
                except KeyError:
                    raise SyntaxError('prefix %r not found in prefix map' % prefix)
            elif (default_namespace and not parsing_attribute):
                yield (ttype, '{%s}%s' % (default_namespace, tag))
            else:
                yield token
            parsing_attribute = False
        else:
            yield token
            parsing_attribute = ttype == '@'

urllib3.filepost.iter_fields:
def iter_fields(fields):
    """
    .. deprecated:: 1.6

    Iterate over fields.

    The addition of :class:`~urllib3.fields.RequestField` makes this function
    obsolete. Instead, use :func:`iter_field_objects`, which returns
    :class:`~urllib3.fields.RequestField` objects.

    Supports list of (k, v) tuples and dicts.
    """
    if isinstance(fields, dict):
        return ((k, v) for (k, v) in six.iteritems(fields))
    return ((k, v) for (k, v) in fields)

lxml.html.clean.word_break:
def word_break(el, max_width=40, avoid_elements=_avoid_word_break_elements, avoid_classes=_avoid_word_break_classes, break_character=unichr(8203)):
    """
    Breaks any long words found in the body of the text (not attributes).

    Doesn't effect any of the tags in avoid_elements, by default
    ``<textarea>`` and ``<pre>``

    Breaks words by inserting &#8203;, which is a unicode character
    for Zero Width Space character.  This generally takes up no space
    in rendering, but does copy as a space, and in monospace contexts
    usually takes up space.

    See http://www.cs.tut.fi/~jkorpela/html/nobr.html for a discussion
    """
    if el.tag in _avoid_word_break_elements:
        return
    class_name = el.get('class')
    if class_name:
        dont_break = False
        class_name = class_name.split()
        for avoid in avoid_classes:
            if avoid in class_name:
                dont_break = True
                break
        if dont_break:
            return
    if el.text:
        el.text = _break_text(el.text, max_width, break_character)
    for child in el:
        word_break(child, max_width=max_width, avoid_elements=avoid_elements, avoid_classes=avoid_classes, break_character=break_character)
        if child.tail:
            child.tail = _break_text(child.tail, max_width, break_character)

requests.utils.dict_from_cookiejar:
def dict_from_cookiejar(cj):
    """Returns a key/value dictionary from a CookieJar.

    :param cj: CookieJar object to extract cookies from.
    :rtype: dict
    """
    cookie_dict = {}
    for cookie in cj:
        cookie_dict[cookie.name] = cookie.value
    return cookie_dict

lxml.ElementInclude._include:
def _include(elem, loader=None, base_url=None, max_depth=DEFAULT_MAX_INCLUSION_DEPTH, _parent_hrefs=None):
    if loader is not None:
        load_include = _wrap_et_loader(loader)
    else:
        load_include = _lxml_default_loader
    if _parent_hrefs is None:
        _parent_hrefs = set()
    parser = elem.getroottree().parser
    include_elements = list(elem.iter(XINCLUDE_ITER_TAG))
    for e in include_elements:
        if e.tag == XINCLUDE_INCLUDE:
            href = urljoin(base_url, e.get('href'))
            parse = e.get('parse', 'xml')
            parent = e.getparent()
            if parse == 'xml':
                if href in _parent_hrefs:
                    raise FatalIncludeError('recursive include of %r detected' % href)
                if max_depth == 0:
                    raise LimitedRecursiveIncludeError('maximum xinclude depth reached when including file %s' % href)
                node = load_include(href, parse, parser=parser)
                if node is None:
                    raise FatalIncludeError('cannot load %r as %r' % (href, parse))
                node = _include(node, loader, href, max_depth - 1, {href} | _parent_hrefs)
                if e.tail:
                    node.tail = ((node.tail or '')) + e.tail
                if parent is None:
                    return node
                parent.replace(e, node)
            elif parse == 'text':
                text = load_include(href, parse, encoding=e.get('encoding'))
                if text is None:
                    raise FatalIncludeError('cannot load %r as %r' % (href, parse))
                predecessor = e.getprevious()
                if predecessor is not None:
                    predecessor.tail = ((predecessor.tail or '')) + text
                elif parent is None:
                    return text
                else:
                    parent.text = ((parent.text or '')) + text + ((e.tail or ''))
                parent.remove(e)
            else:
                raise FatalIncludeError('unknown parse type in xi:include tag (%r)' % parse)
        elif e.tag == XINCLUDE_FALLBACK:
            parent = e.getparent()
            if (parent is not None and parent.tag != XINCLUDE_INCLUDE):
                raise FatalIncludeError('xi:fallback tag must be child of xi:include (%r)' % e.tag)
        else:
            raise FatalIncludeError('Invalid element found in XInclude namespace (%r)' % e.tag)
    return elem

lxml._elementpath.prepare_star:
def prepare_star(next, token):

    def select(result):
        for elem in result:
            for e in elem.iterchildren('*'):
                yield e
    return select

lxml._elementpath.prepare_child:
def prepare_child(next, token):
    tag = token[1]

    def select(result):
        for elem in result:
            for e in elem.iterchildren(tag):
                yield e
    return select
